H=Path(__file__).resolve().parent;ROOT=H.parents[2];REPO=ROOT.parents[1];OUT=ROOT/'robustness/cycle06_access_v2_official_tiers';MODEL=ROOT/'model/output_cycle06_access_v2_baseline'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p,j):p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
def main():
 if (H/'freeze_manifest.json').exists():raise FileExistsError('Frozen review: use a new sibling independent review directory')
 protocol=json.loads((OUT/'protocol.json').read_text());receipt=json.loads((OUT/'official_tier_diagnostic_receipt.json').read_text());before=protocol['source_sha256'];assert before==receipt['source_sha256'];assert all(sha(Path(k))==v for k,v in before.items());paths={Path(k).name:Path(k) for k in before};inventory=pd.read_parquet(paths['official_monitoring2021_reporting_organizations.parquet']);identity=pd.read_parquet(paths['official_monitoring2021_typed_address_identity.parquet']);roles=pd.read_parquet(paths['source_settlement_statistical_role_primary2021_v3.parquet']);admission=json.loads(paths['audit.json'].read_text());assert admission['all_checks_passed'] and sha(paths['official_monitoring2021_typed_address_identity.parquet'])==admission['accepted_typed_identity_sha256'];assert inventory.reporting_unit_key.is_unique and identity.reporting_unit_key.is_unique;assert inventory.source_reference_data_year.eq(2021).all()
 source={str(p):sha(p) for p in [OUT/'protocol.json',OUT/'official_tier_diagnostic_receipt.json',OUT/'candidate_official_org_witness_diagnostic.parquet',MODEL/'candidate_centers.parquet',MODEL/'nodes.parquet',Path(__file__)]};manifest=json.loads((MODEL/'output_manifest.json').read_text());assert sha(MODEL/'nodes.parquet')==manifest['files']['nodes.parquet']['sha256'];assert sha(MODEL/'candidate_centers.parquet')==manifest['files']['candidate_centers.parquet']['sha256']
