 cfg=json.loads(paths['config_baseline_final.json'].read_text());assert not any('monitoring' in json.dumps(v).lower() for v in cfg['components']);external_sha={sha(paths['official_monitoring2021_reporting_organizations.parquet']),sha(paths['official_monitoring2021_typed_address_identity.parquet'])};assert all(sha((Path(v['path']) if Path(v['path']).is_absolute() else REPO/v['path'])) not in external_sha for v in cfg.get('layers',[]))
 positive=pd.DataFrame(selected,columns=['reporting_unit_key','sector','uid']);assert len(positive)==receipt['scope_gate']['ordinary_accepted_positive_reporting_rows'];assert set(positive.uid)<=set(pd.read_parquet(MODEL/'nodes.parquet',columns=['id']).id)
