 for i,row in enumerate(centers.itertuples(index=False)):
  n=nodes.loc[row.id];rr=role.get(row.id,pd.NA);p=n.population_2021
  if bool(n._population_axis_row) and pd.notna(p) and p>=0 and pd.notna(row.region) and pd.notna(rr):
   band=int(np.searchsorted(edges,p,side='right')-1);interval=str(pd.Interval(edges[band],edges[band+1],closed='left'));key=f"{row.region}|{'rural' if bool(rr) else 'nonrural'}|{interval}";assert key==candidate_export.loc[row.id,'stratum'];strata.setdefault(key,[]).append(i);valid[i]=True
 rank=centers.intrinsic_empirical_rank.to_numpy(dtype=float)
 for sector in ['vpo','spo']:
  observed=positive[positive.sector.eq(sector)];lookup=observed.uid.value_counts();counts=np.array([int(lookup.get(uid,0)) for uid in centers.id]);witness=counts>0;assert np.array_equal(counts,candidate_export.loc[centers.id,sector+'_positive_org_witness_count'].to_numpy());groups=[]
  for key in sorted(strata):
   ii=np.array(strata[key]);x=rank[ii];y=witness[ii].astype(float)
   if len(ii)>=5 and len(set(x))>=2 and len(set(y))==2:groups.append((x,y-y.mean(),y.astype(bool)))
  denom=sum(len(x) for x,y,b in groups);offset=sum((Fraction(int(x.sum())*int(b.sum()),len(x)) for x,y,b in groups),Fraction(0))
  def measure(permute):
   total=0.;replay=0.;integer=0
   for x,y,b in groups:
    xx=rng.permutation(x) if permute else x;total+=float(np.dot(xx,y));replay+=float(np.sum((xx-xx.mean())*y));integer+=int(xx[b].sum())
   return total/denom,replay/denom,integer
  cov,authored_cov,obs_integer=measure(False);draws=[measure(True) for _ in range(1999)];null=np.array([v[0] for v in draws]);authored_null=np.array([v[1] for v in draws]);integer_null=np.array([v[2] for v in draws]);actual=pd.read_csv(OUT/(sector+'_conditional_permutations.csv')).conditional_covariance.to_numpy();error=np.abs(null-actual);recovered_integer=np.rint(actual*denom+float(offset)).astype('int64');assert np.array_equal(recovered_integer,integer_null),'Frozen author statistics imply different integer-rank sums';assert len(actual)==1999 and error.max()<1e-13 and np.abs(authored_null-actual).max()<1e-13
  pvalue=float((1+np.count_nonzero(np.abs(null)>=abs(cov)))/2000);author_p=float((1+np.count_nonzero(np.abs(authored_null)>=abs(authored_cov)))/2000);distance=abs(Fraction(obs_integer)-offset);exact_tail=sum(abs(Fraction(int(s))-offset)>=distance for s in integer_null);exact_p=(1+exact_tail)/2000.;reported=next(s for s in receipt['summary'] if s['sector']==sector);assert abs(cov-reported['conditional_covariance'])<1e-13 and author_p==reported['two_sided_exploratory_permutation_p'];assert denom==reported['controlled_centers'] and len(groups)==reported['eligible_strata'];assert len(observed)==reported['accepted_programme_positive_reporting_rows'] and counts.sum()==reported['accepted_reporting_rows_at_candidate_centers'] and witness.sum()==reported['positive_candidate_centers'];assert int((~valid).sum())==reported['centers_missing_controls']
  print('TAIL_DIAGNOSTIC',sector,'reported',author_p,'dot_float',pvalue,'exact_inclusive',exact_p,'offset',str(offset),flush=True)
  tab=[]
